package com.publicmonitor.backend.domain.document.service;

import java.util.regex.Pattern;

/** Stable categories shared with the analysis contract; labels are never generated by a model. */
public enum BusinessType {
    RND("연구개발(R&D)", "새로운 기술을 연구하거나 기존 기술의 성능을 높이는 사업입니다.", "R&D|연구개발(?!기업|인력|실적)|기술개발|공동연구"),
    DEMONSTRATION("실증·시범", "실제 환경에서 기술이나 서비스의 성능과 효과를 확인하는 사업입니다.", "실증|테스트베드|PoC|시범(?:사업|운영|적용|적으로참여)|현장검증"),
    COMMERCIALIZATION("제품화·사업화", "시제품 제작과 제품 고도화 등 시장에 내놓을 제품을 준비하는 사업입니다.", "시제품|제품화|사업화|양산|제품고도화|제품디자인"),
    ADOPTION("설비·시스템 도입", "설비나 시스템을 구축·도입하거나 작업환경을 개선하는 사업입니다.", "인프라구축|시스템(?:을)?구축|시스템(?:을)?도입|솔루션도입|(?:설비|시설)(?:를|을|의)?(?:도입|구축|개선|교체|구매|설치|지원)|장비도입|장비구축|시설개선|환경개선|환경조성|스마트공장|공정개선"),
    CERTIFICATION("시험·인증", "시험평가와 인증 취득, 규격·배출량 검증을 지원하는 사업입니다.", "인증(?:을|의)?(?:취득|획득|비용|수수료|시험|지원)|(?<!정부)인증(?!기업|기관|업체|보유|실적)|시험평가|시험비|제3자검증|배출량검증|성능시험|규격시험"),
    MARKET("판로·해외진출", "고객과 판로를 확보하거나 국내외 시장 진출을 지원하는 사업입니다.", "판로|마케팅|해외진출|수출(?:지원|마케팅|상담|바우처|판로|촉진)|전시회|박람회|구매상담|시장진출"),
    FINANCE("자금·금융", "융자·보증·투자 등 기업의 자금 조달을 지원하는 사업입니다.", "융자|이차보전|이자지원|신용보증|기술보증|보증지원|직접투자|투자유치|정책자금"),
    WORKFORCE("인력·고용·교육", "기업의 채용·고용 유지와 인력 교육·훈련을 지원하는 사업입니다.", "채용지원|고용지원|고용장려|인건비지원|인력양성|인재양성|교육지원|직무교육|훈련지원|교육훈련|훈련과정|역량강화코칭"),
    ADVISORY("조사·컨설팅·전문지원", "조사·기획·컨설팅과 법률·회계·지식재산 등 전문 업무를 지원하거나 수행하는 사업입니다.", "컨설팅|정책연구|조사용역|시장조사|기술지도|(?:기초자료|현황|실태|사례|타당성)조사|현황분석|(?:기본구상|기본계획|개선방안)(?:안)?(?:수립|검토)|전문자문|법률지원|회계지원|(?:법률|노무|회계)상담|고충상담|특허(?!보유)|지식재산|출원"),
    SPACE("공간·입주", "기업이 사용할 사무실·연구실 등 공간과 입주 기회를 제공하는 사업입니다.", "입주|사무공간|보육공간|공간지원|공간제공|연구공간");

    private final String label;
    private final String description;
    private final Pattern signal;

    BusinessType(String label, String description, String signal) {
        this.label = label;
        this.description = description;
        this.signal = Pattern.compile(signal, Pattern.CASE_INSENSITIVE);
    }
    public String label() { return label; }
    public String description() { return description; }
    boolean matches(String text) { return text != null && signal.matcher(text.replaceAll("\\s+", "")).find(); }
    int position(String text) {
        var matcher = signal.matcher(text.replaceAll("\\s+", ""));
        return matcher.find() ? matcher.start() : Integer.MAX_VALUE;
    }
}
